// Каналы-ориентиры. Источник правды — automation/n8n/channels.json; при правке обновить и здесь.
// id (UC…) приоритетнее handle, если заполнен.
const channels = [
  { "group": "Прямые конкуренты", "name": "Example Channel", "handle": "@example", "id": "" }
];

return channels.map(c => ({ json: c }));

// HTTP-нода отдаёт ответы в том же порядке, что и входные каналы
const list = $('Channels list').all();
const out = [];
$input.all().forEach((item, i) => {
  const ch = (item.json.items || [])[0];
  if (!ch) return;
  out.push({
    json: {
      ...list[i].json,
      channelId: ch.id,
      title: ch.snippet.title,
      subscribers: Number(ch.statistics.subscriberCount || 0),
      // UULF… — только длинные видео канала (без Shorts): иначе у каналов с частыми Shorts
      // в последние 50 загрузок не попадает ни одного видео длиннее 3 минут
      uploads: 'UULF' + ch.id.slice(2),
    },
  });
});
if (!out.length) throw new Error('Ни один канал не найден — проверьте handles в Channels list');
return out;

const chans = $('Uploads playlists').all();
return $input.all()
  .map((item, i) => ({
    json: {
      channelId: chans[i].json.channelId,
      ids: (item.json.items || []).map(v => v.contentDetails.videoId).join(','),
    },
  }))
  .filter(x => x.json.ids);

// outlier score = просмотры / медиана канала; velocity = просмотры / дни с публикации.
// Отбрасываем видео короче 3 минут (Shorts) и моложе 3 дней (ещё не набрали просмотры).
// У каналов с медианой ниже minMedian score шумит (271 просмотр медианы → 6 тыс. дают score 24),
// поэтому их видео не идут в outliers/fresh, а выводятся отдельно в smallTop.
const cfg = $('Config').first().json;
const minScore = Number(cfg.minScore || 2);
const minMedian = Number(cfg.minMedian ?? 1000);
const now = $now.toMillis();

const duration = iso => {
  const m = /PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/.exec(iso || '') || [];
  return (Number(m[1]) || 0) * 3600 + (Number(m[2]) || 0) * 60 + (Number(m[3]) || 0);
};
const median = arr => {
  const s = [...arr].sort((a, b) => a - b);
  const n = s.length;
  if (!n) return 0;
  return n % 2 ? s[(n - 1) / 2] : (s[n / 2 - 1] + s[n / 2]) / 2;
};

const byChannel = {};
for (const item of $input.all()) {
  for (const v of item.json.items || []) (byChannel[v.snippet.channelId] ||= []).push(v);
}

const channels = [];
const videos = [];
for (const c of $('Uploads playlists').all().map(i => i.json)) {
  const vs = (byChannel[c.channelId] || [])
    .map(v => {
      const ageDays = Math.max((now - Date.parse(v.snippet.publishedAt)) / 86400000, 1);
      const views = Number(v.statistics.viewCount || 0);
      return {
        id: v.id,
        title: v.snippet.title,
        channel: c.name,
        group: c.group,
        publishedAt: v.snippet.publishedAt.slice(0, 10),
        ageDays,
        views,
        velocity: views / ageDays,
        durationSec: duration(v.contentDetails.duration),
      };
    })
    .filter(v => v.durationSec >= 180 && v.ageDays >= 3);
  const med = median(vs.map(v => v.views));
  vs.forEach(v => { v.score = med ? v.views / med : 0; });
  channels.push({
    name: c.name,
    group: c.group,
    title: c.title,
    subscribers: c.subscribers,
    analyzed: vs.length,
    median: med,
    small: med > 0 && med < minMedian,
    best: vs.reduce((m, v) => Math.max(m, v.score), 0),
  });
  videos.push(...vs);
}

const small = new Set(channels.filter(c => c.small).map(c => c.name));
const byScore = (a, b) => b.score - a.score;
const main = videos.filter(v => !small.has(v.channel));
const outliers = main.filter(v => v.score >= minScore).sort(byScore).slice(0, 25);
const fresh = main.filter(v => v.ageDays <= 30).sort(byScore).slice(0, 10);
// По 3 лучших видео с каждого малого канала — для справки, без комментариев
const smallTop = [...small].flatMap(name => videos.filter(v => v.channel === name).sort(byScore).slice(0, 3));

return [{ json: { minScore, minMedian, channels, outliers, fresh, smallTop } }];

const today = $now.setZone('Europe/Berlin').toFormat('yyyy-MM-dd');
const { minScore, minMedian, channels, outliers, fresh, smallTop = [] } = $('Score videos').first().json;

const fmt = n => Math.round(n).toLocaleString('de-DE');
const esc = s => String(s).replace(/\|/g, '\\|').replace(/\[/g, '\\[').replace(/\]/g, '\\]');
const clean = s => String(s).replace(/\s+/g, ' ').trim();
const cut = (s, n) => s.length > n ? s.slice(0, n - 1) + '…' : s;
const link = v => `[${esc(v.title)}](https://youtu.be/${v.id})`;

// Комментарии: ответы HTTP-ноды идут в порядке Comment targets
const targets = $('Comment targets').all().map(i => i.json.videoId);
const comments = {};
$input.all().forEach((item, i) => {
  const id = targets[i];
  if (!id) return;
  comments[id] = (item.json.items || [])
    .map(t => t.snippet.topLevelComment.snippet)
    .sort((a, b) => b.likeCount - a.likeCount)
    .slice(0, 10)
    .map(s => ({ text: cut(clean(s.textDisplay), 300), likes: s.likeCount }));
});

// Каналы, которые не удалось найти по handle/id
const resolved = $('YT resolve channel').all();
const missing = $('Channels list').all()
  .map((c, i) => ({ c: c.json, r: resolved[i] && resolved[i].json }))
  .filter(x => !x.r || !(x.r.items || []).length)
  .map(x => `- ${x.c.name} (\`${x.c.id || x.c.handle}\`)${x.r && x.r.error ? ` — ${clean(x.r.error.message || x.r.error)}` : ''}`);

const videoRow = v =>
  `| ${v.score.toFixed(1)} | ${link(v)} | ${esc(v.channel)} | ${v.group} | ${fmt(v.views)} | ${v.publishedAt} | ${fmt(v.velocity)} |`;
const videoHead = [
  '| Score | Видео | Канал | Группа | Просмотры | Опубликовано | Просм./день |',
  '| --- | --- | --- | --- | --- | --- | --- |',
];

const md = [
  '---',
  'source: "YouTube Data API v3 через n8n (workflow trends)"',
  `date: ${today}`,
  'tags:',
  '  - тренды',
  '  - конкуренты',
  '---',
  '',
  `# Тренды по каналам-ориентирам — ${today}`,
  '',
  'Score = просмотры видео / медиана канала по последним 50 загрузкам. Видео короче 3 минут и моложе 3 дней не учитываются.',
  `Каналы с медианой ниже ${fmt(minMedian)} просмотров в outlier-ы и свежие не попадают — их лучшие видео в разделе «Малые каналы».`,
  '',
  `## Outlier-видео (score ≥ ${minScore})`,
  '',
  ...(outliers.length ? [...videoHead, ...outliers.map(videoRow)] : ['_Нет видео выше порога._']),
  '',
  '## Свежие видео (≤ 30 дней), лучшие по score',
  '',
  ...(fresh.length ? [...videoHead, ...fresh.map(videoRow)] : ['_Нет свежих видео._']),
  '',
  ...(smallTop.length ? [
    `## Малые каналы (медиана < ${fmt(minMedian)})`,
    '',
    ...videoHead,
    ...smallTop.map(videoRow),
    '',
  ] : []),
  '## Комментарии к топ-outlier-ам',
  '',
  ...outliers.filter(v => comments[v.id]).flatMap(v => [
    `### ${link(v)} — ${esc(v.channel)}`,
    '',
    ...(comments[v.id].length
      ? comments[v.id].map(c => `- (${c.likes} ♥) ${c.text}`)
      : ['_Комментарии недоступны._']),
    '',
  ]),
  '## Каналы',
  '',
  '| Канал | Группа | Подписчики | Медиана просмотров | Видео в выборке | Лучший score |',
  '| --- | --- | --- | --- | --- | --- |',
  ...channels.map(c =>
    `| ${esc(c.title)}${c.small ? ' (малый)' : ''} | ${c.group} | ${fmt(c.subscribers)} | ${fmt(c.median)} | ${c.analyzed} | ${c.best.toFixed(1)} |`),
  '',
  ...(missing.length ? ['## Не найдены', '', ...missing, ''] : []),
].join('\n');

return [{
  json: {
    path: `docs/raw/trends/${today}-trends.md`,
    message: `trends: отчёт по каналам-ориентирам ${today}`,
    content: Buffer.from(md, 'utf8').toString('base64'),
  },
}];
